/* Yoast FAQ Block - Accordion Style */
.schema-faq-question {
	font-family: Campton, system-ui;
	font-weight: 500;
}

.wp-block-yoast-faq-block {
	margin-bottom: 2.5rem;
}

.schema-faq:not(.is-style-just-text) .schema-faq-section {
	position: relative;
	border-style: solid;
	border-width: 1px 0 0 0;
	border-color: var(--wp--preset--color--border-light, #e5e1d7);
}

.schema-faq:not(.is-style-just-text).wp-block-yoast-faq-block {
	border-bottom: 1px solid var(--wp--preset--color--border-light, #e5e1d7);
}

.schema-faq:not(.is-style-just-text) .schema-faq-question {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 1em 2.5em 1em 3em;
	margin-block: 0;
	max-width: 100%;
	background-color: transparent;
