/* mega menu */
header .wp-block-navigation__container {
	align-items: start;

	li {
		margin-block: 0;
	}
}

:root .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content {
	padding-top: 1.5rem;
}

.wp-block-ollie-mega-menu__toggle .wp-block-ollie-mega-menu__toggle-icon svg {
	width: 12px !important;
}

:is(.wp-block-ollie-mega-menu__menu-container) :is(h1,h2,h3,h4,h5,h5) {
	--font-family: Campton, 'Campton Light', system-ui;
	--h1-font-family: inherit;
	--h1-font-size: var(--wp--preset--font-size--xx-large, 3rem);
	--h1-font-weight: 500;
	--h2-font-family: inherit;
	--h2-font-size: var(--wp--preset--font-size--x-large, 2.5rem);
	--h2-font-weight: 500;
	--h3-font-family: inherit;
	--h3-font-size: var(--wp--preset--font-size--large, 2rem);
	--h3-font-weight: 500;
	--h4-font-family: inherit;
	--h4-font-weight: 500;
	--h5-font-family: inherit;
	--h5-font-weight: 500;
	--h6-font-family: inherit;
	--h6-font-weight: 500;
	--bold-font-weight: 500;

	color: inherit;
	font-family: inherit;
}

.wp-block-navigation__responsive-container,
.wp-block-ollie-mega-menu__menu-container {
	line-height: 1.3;

	figure a {
		display: block;
	}

	.is-product-collection-layout-carousel .wc-block-product {
		min-width: 31.5%;
		display: flex;
		flex-direction: column;
		align-items: center;
	}
}

:root:root a.wp-block-navigation-item__content,
:root:root:root .wp-block-ollie-mega-menu__toggle {
	display: flex;
	align-items: center;

	&:is([aria-current="page"], [aria-expanded="true"]) {
		color: var(--wp--preset--color--accent-2);
	}
}

.is-product-collection-layout-carousel .wc-block-product,
.cb-has-abs-link {
	position: relative;
	transition-property: backdrop-filter, filter,opacity,color,background-color;
  	transition-duration: .2s;

	&:has(a:hover) {
		color: var(--color-header-top-text-hover) !important;
	}

	&.is-style-background-blur:hover {
		background-color: rgba(255, 255, 255, 0.15);
		backdrop-filter: blur(60px);
	}

	img {
		transition-property: filter,opacity;
  		transition-duration: .2s;
	}

	&:has(a:hover) img {
		filter: brightness(109%);
		opacity: .9;
	}

	a::after {
		content: "";
		position: absolute;
		top: 0;
		left: 0;
		display: block;
		width: 100%;
		height: 100%;
	}
}

:root .cb-background-blur,
:root:root .is-style-background-blur {
	border-radius: 8px;
	background-color: rgba(126, 126, 126, 0.15);
	backdrop-filter: blur(50px);
}

#cb-mega-nav {

	> nav {
		margin-top: 0;
	}
	a {
		transition-property: background-color,color,opacity;
  		transition-duration: .2s;

	}
}

:where(.wp-block-ollie-mega-menu__menu-container) :is(a,h1,h2,h3,h4,h5,h5) {
	color: inherit;
}

.wp-block-woocommerce-product-collection {
	width: 100% !important;
	max-width: calc(100% - 80px);
}

.wp-block-woocommerce-product-collection ul {
	margin-inline: 0;
}


/* Mobile Navigation
--------------------------------------------- */

.wp-block-navigation__responsive-container.is-menu-open.has-modal-open {
	padding: var(--wp--preset--spacing--medium);
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content {
	gap: var(--wp--preset--spacing--medium);
}

.wp-block-navigation__responsive-container.is-menu-open.has-modal-open .wp-block-navigation__container {
	width: 100%;
	gap: 5px !important;
}

.wp-block-navigation__responsive-container.is-menu-open.has-modal-open .wp-block-page-list {
	width: 100%;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .has-child .wp-block-navigation__submenu-container {
	border-radius: 0;
	margin: 0;
	padding: 5px 0 0 20px;
	align-items: flex-start;
	flex-direction: column;
	gap: 5px;
	width: 100%;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .wp-block-navigation__submenu-icon {
	display: block;
	position: absolute;
	right: 0;
	top: 5px;
	height: auto;
	width: 60px;
	padding: 15px 0;
	margin: 0;
	z-index: 10;
}

body.rtl .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .wp-block-navigation__submenu-icon {
	left: 0;
	right: auto;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .wp-block-navigation__submenu-icon svg {
	height: 16px;
	margin: 0;
}

/* mobile submenu display */
.wp-block-navigation__mobile-menu-content {
	interpolate-size: allow-keywords;

	.wp-block-navigation .has-child .wp-block-navigation__submenu-container {
		transition: height 0.2s, opacity 0.3s !important;
	}
}

:root:root .wp-block-navigation-submenu__toggle[aria-expanded="false"] ~ .wp-block-navigation__submenu-container {
	height: 0;
	opacity: 0;
	overflow: hidden;
	visibility: hidden;
}

:root:root .wp-block-navigation-submenu__toggle[aria-expanded="true"] ~ .wp-block-navigation__submenu-container {
	opacity: 1;
	height: auto;
	visibility: visible;
}

.wp-block-navigation__responsive-container.is-menu-open.has-modal-open .wp-block-navigation__container li:not(.wp-social-link) {
	width: 100%;
	padding: 0 0;
	position: relative;
}

/* Mobile menu links */
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .wp-block-navigation-item__content {
	width: 100%;
	font-size: var(--wp--preset--font-size--base);
	padding: 15px 60px 15px 15px;
	border-radius: 5px;
}

body.rtl .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__responsive-container-content .wp-block-navigation-item__content {
	padding: 15px 15px 15px 60px;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container .current-menu-item > .wp-block-navigation-item__content,
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container .wp-block-navigation-item:hover > .wp-block-navigation-item__content {
	transition: .3s ease;
	text-decoration: none;
	background: color-mix(in srgb, currentColor, transparent 97%);
	-webkit-tap-highlight-color: transparent;
}

.wp-block-navigation__container .wp-block-navigation-item:has(.wp-block-navigation__submenu-container:hover) > .wp-block-navigation-item__content {
	background: transparent;
}

/* Mobile menu open button */
.wp-block-navigation__responsive-container-close,
.wp-block-navigation__responsive-container-open {
	padding: 4px;
	border-radius: 3px;
	background: var(--wp--preset--color--tertiary);
	color: var(--wp--preset--color--main);
}

/* Mobile menu close button */
.wp-block-navigation__responsive-container-close {
	background: var(--wp--preset--color--tertiary);
	color: var(--wp--preset--color--main);
}

.wp-block-ollie-mega-menu__menu-container {
	font-weight: 400;
}

/* WC Product slider */
.wc-block-next-previous-buttons {
	margin: 0;
	padding: 0;
}

.wc-block-next-previous-buttons__button {
	--cb-slide-opacity: 0;

	position: absolute;
	transition-property: color, background-color, box-shadow;
	transition-duration: .2s;

	height: 100%;
	top: 0;
	right: 0;
	color: #fff !important;
	border-radius: 0 8px 8px 0 !important;
	box-shadow: none !important;
	background-color: rgba(255, 255, 255, var(--cb-slide-opacity, 0.2)) !important;

	&:first-child {
		border-radius: 8px 0 0 8px !important;
		left: 0;
	}

	svg {
		padding: 0;
	}

	&:not([aria-disabled="true"]):hover {
		--cb-slide-opacity: 0.2;
	}

	&[aria-disabled="true"] {
		--cb-slide-opacity: 0;
	}
}

.is-product-collection-layout-carousel {
	gap: 1rem;
}

@keyframes overlay-menu__fade-in-animation {
	from {
		opacity: 0;
		transform: translateX(-100vw);
	}
	to {
		opacity: 1;
		transform: translateX(0);
	}
}

@keyframes expand-mobile-submenu {
  to {
    height: auto;
  }
}

.wp-block-navigation__responsive-container.is-menu-open {
	animation: overlay-menu__fade-in-animation .2s ease-out;
	animation-fill-mode:forwards
}

.safe-svg-cover svg[fill="none"] {
	fill: none;
}

.wp-block-ollie-mega-menu .wp-block-ollie-mega-menu__toggle[aria-expanded="true"] ~ .wp-block-ollie-mega-menu__menu-container > .wp-block-cover {
	min-height: 662px;
	align-items: start;
}

.wp-block-navigation__responsive-container-close {
	right: unset;
	left: 0.75rem;
	top: 0.75rem;
}

.wp-block-navigation__submenu-container .has-child > .wp-block-navigation-submenu__toggle {

	+ .wp-block-navigation__submenu-icon {
		padding: 0 !important;
		line-height: 32px;
		transform: translateX(-30px);
	}
}

:root .u-flex-1 {
	flex: 1;
}


