/**
 * The following styles will provide an attempt to normalize the sliders
 */

/* Reset some style. Using body to push specificity */
body .metaslider .coin-slider,
body .metaslider .nivoSlider,
body .metaslider .nivoSlider img,
body .metaslider .rslides,
body .metaslider .rslides li,
body .metaslider .flexslider ul.slides,
body .metaslider .flexslider .slides li,
body .metaslider .flexslider .slides ul,
body .metaslider .flexslider .slides ol,
body .metaslider .flexslider .slides img,
body .metaslider .flexslider .flex-direction-nav,
body .metaslider .flexslider .flex-direction-nav li {
    border: 0;
    margin: 0;
    list-style-type: none;
    list-style: none;
    padding: 0;
    line-height: normal;
    max-width: none;
    max-height: none;
}

.metaslider {
    position: relative;
    z-index: 0;
}

/* Avoids overflow when slideshow takes the whole window' width - The fullwidth class needs to be added in the slideshow settings. */
.metaslider.fullwidth {
	overflow: hidden;
}

.metaslider .caption {
    padding: 5px 10px;
    word-wrap: break-word;
}

.metaslider .caption-wrap {
    position: absolute;
    bottom: 0;
    left: 0;
    background: black;
    color: white;
    opacity: 0.7;
    margin: 0;
    display: block;
    width: 100%;
    line-height: 1.4em;
}

.metaslider img {
    height: auto;
    padding: 0;
    margin: 0;
    -moz-user-select: none;
}

.metaslider a {
    outline: none;
}

.metaslider.ms-left {
    float: left;
    margin: 0 20px 20px 0;
}

.metaslider.ms-right {
    float: right;
    margin: 0 0 20px 20px;
}

.metaslider li:before,
.metaslider li:after {
    content: "" !important;
    display: none !important;
    bottom: auto !important;
    margin: 0 !important;
}

.metaslider .flexslider .slides li .caption-wrap .caption img {
    max-width: 100%;
    height: auto;
    display: inline;
}

.metaslider .slides img:not(.caption img) {
	width: 100%;
	display: block;
}

.metaslider .flex-pauseplay a {
    box-sizing: border-box;
	height: 30px;
	width: 30px;
}

/* Flexslider */

.metaslider .flexslider {
    background: none;
    box-shadow: none;
    -webkit-box-shadow: none;
    -moz-box-shadow: none;
    -o-box-shadow: none;
    border: 0;
    margin: 0 0 40px;
    max-width: none;
    max-height: none;
}

.metaslider .flex-control-nav {
    border: 0;
    margin: auto;
    list-style-type: none;
    list-style: none;
    padding: 0;
	bottom: -27px;
    line-height: 11px;
    z-index: 2;
}

.metaslider.has-dots-onhover-navigation .flexslider .flex-control-paging {
    opacity: 1;
    transition: opacity .3s ease;
}
.metaslider.has-dots-onhover-navigation:hover .flexslider .flex-control-paging {
    opacity: 1 !important;
}

.metaslider-flex.ms-theme-default .flex-next:focus {
    background: url("/assets/images/theme/bg_direction_nav.png") scroll right 0 transparent!important;
    height: 27px!important;
}
.metaslider-flex.ms-theme-default .flex-prev:focus {
    background: url("/assets/images/theme/bg_direction_nav.png") scroll left 0 transparent!important;
    height: 27px!important;
}

/** move margin from list items to anchors */
.metaslider .flex-control-nav li {
	margin: 0;
}

.metaslider .flex-control-nav li a {
	margin: 0 6px;
	padding: 0;
	text-indent: 9999px;
	overflow: hidden;
}

.metaslider .flexslider .slides li {
    position: relative;
    height: auto;
}

/** fix for users with RTL languages */
.metaslider .flex-viewport {
    direction: ltr;
}

/** add transition effects to firefox **/
.metaslider .flex-direction-nav a {
    -moz-transition: all .3s ease;
    transition: all .3s ease;
}

.metaslider .flexslider .slides p {
    margin: 0;
}

.metaslider .flexslider.filmstrip {
	margin-top: 10px;
}

.metaslider .flexslider.filmstrip .slides li {
    cursor: pointer;
    opacity: 0.5;
}

.metaslider .flexslider.filmstrip .slides li.flex-active-slide,
.metaslider .flexslider.filmstrip .slides li:hover,
.metaslider .flexslider.filmstrip .slides li:focus {
    opacity: 1.0 !important;
}

.metaslider .flex-control-thumbs {
    margin: 5px -5px 0 -5px;
}

.metaslider .flex-control-thumbs li {
    width: auto;
    margin: 5px;
}

.metaslider ol.flex-control-thumbs img,
#content .metaslider ol.flex-control-thumbs img {
    margin: 10px 5px 0;
    width: auto;
}

.metaslider.nav-hidden .flexslider {
    margin-bottom: 0;
}

.metaslider.nav-hidden.add-margin .flexslider {
    margin-bottom: 40px;
}

/* Arrow styles to use background images (old style) */
/* which makes it compatible with the theme builder */

.metaslider .flexslider .flex-direction-nav li a:before {
    content:none!important;
}
.metaslider .flexslider .flex-direction-nav li a {
    width: 30px;
    height: 30px;
    border: 0;
    margin: -20px 0 0;
    box-shadow: none!important;
    display: block;
    background-color: transparent;
    background-image: url("/assets/images/theme/bg_direction_nav.png");
    background-repeat:  no-repeat;
    position: absolute;
    right: 10px;
    top: 50%;
    z-index: 10;
    cursor: pointer;
    text-indent: -9999px;
    opacity: 1;
    -webkit-transition: all .3s ease;
       -moz-transition: opacity .25s ease-in-out;
            transition: all .3s ease;
}
.metaslider.has-onhover-arrows .flexslider .flex-direction-nav li a {
    opacity: 0;
}
.metaslider.has-onhover-arrows:hover .flexslider .flex-direction-nav li a{
    opacity: 1;
}

.metaslider .flex-direction-nav .flex-prev {
    background-position: left 0;
    left: 10px;
}
.metaslider .flex-direction-nav .flex-next {
    background-position: right 0;
    text-align: left;
    /* Fix for single character text */
    text-indent: 9999px;
}
.metaslider .flexslider:focus-within .flex-next,
.metaslider .flexslider:hover .flex-next {
    opacity: 0.8;
    
}
.metaslider .flexslider:focus-within .flex-prev,
.metaslider .flexslider:hover .flex-prev {
    opacity: 0.8;
    /* Fix for single character text */
    text-indent: -9999px;
}
.metaslider .flexslider:focus-within .flex-next:focus,
.metaslider .flexslider:focus-within .flex-prev:focus,
.metaslider .flexslider:hover .flex-next:hover,
.metaslider .flexslider:hover .flex-prev:hover {
    opacity: 1;
}
.metaslider .flexslider .flex-next:focus,
.metaslider .flexslider .flex-prev:focus {
	outline: -webkit-focus-ring-color auto 5px;
}
.metaslider .flexslider .flex-direction-nav .flex-disabled {
    cursor: default;
    pointer-events: none;
}
.metaslider .flexslider .flex-control-nav a {
	box-shadow: none !important;
}
.metaslider .flexslider .flex-control-nav a:focus {
	outline: -webkit-focus-ring-color auto 5px;
}
.metaslider .flexslider .slides > li {
    position: relative;
}
.metaslider .flexslider .flex-pauseplay .flex-play,
.metaslider .flexslider .flex-pauseplay .flex-pause {
    width: 30px;
    height: 30px;
    background: #000;
    color: #fff;
    text-align: center;
    padding: 0 8px;
    border-radius: 50px;
    text-decoration: none;
    line-height: 30px;
    font-size: 16px;
}
.metaslider .flexslider .flex-pauseplay a:before {
    font-size: 16px;
}
.metaslider .flexslider .flex-pauseplay .flex-play:focus,
.metaslider .flexslider .flex-pauseplay .flex-pause:focus {
    background: #000;
    color: #fff;
	outline: 2px solid #fff;
}
.metaslider .flexslider .flex-pauseplay .flex-play:before {
    margin-left: 4px;
}
.metaslider .flexslider .flex-pauseplay .flex-pause:before {
    margin-left: 1px;
}

/* Responsive Slides */
.metaslider .rslides_nav,
.metaslider .rslides_tabs a {
    box-shadow: none !important;
}
.metaslider .rslides_tabs {
    margin: 0 0 40px;
}

.metaslider .rslides_nav:focus,
.metaslider .rslides_nav:hover {
    color: #ffffff;
}

.metaslider-responsive.no-text .rslides_nav{
	width: 30px;
	height: 30px;
	border: 0;
	margin: 0 5px;
	box-shadow: none !important;
	display: block;
	background-color: transparent;
	background-image: url("/assets/images/theme/bg_direction_nav.png");
	background-repeat: no-repeat;
	position: absolute;
	top: 50%;
	z-index: 10;
	cursor: pointer;
	text-indent: -9999px;
	opacity: 1;
	-webkit-transition: all .3s ease;
	-moz-transition: opacity .25s ease-in-out;
	transition: all .3s ease;
}
.metaslider-responsive.no-text .rslides_nav.next {
	background-position: right 0;
}

/* Nivo Slider */
div.metaslider .theme-default .nivoSlider {
   -webkit-box-shadow: 0 0 0;
      -moz-box-shadow: 0 0 0;
           box-shadow: 0 0 0;
}

.metaslider .slider-wrapper .nivo-directionNav a,
.metaslider .slider-wrapper .nivo-controlNav a,
.metaslider .slider-wrapper img {
    border: 0;
    box-shadow: none;
    /* margin: 0; */
    list-style-type: none;
    list-style: none;
    padding: 0;
    line-height: normal;
    max-width: none;
    max-height: none;
}
div.metaslider .slider-wrapper .nivo-controlNav a {
    transition: none;
}

/* Coin Slider */
.metaslider .coin-slider {

    /* This keeps the slider from spilling out the container */
    max-width: 100%;
    overflow:hidden;
}
.metaslider .coin-slider .cs-buttons a,
.metaslider .coin-slider > a {
	box-shadow: none !important;
}
.metaslider .coin-slider a[href="javascript:void(0)"] {
	cursor: default !important;
}

/* Admin Bar */
#wpadminbar #wp-admin-bar-ms-main-menu .ab-item #metaslider-main-menu-icon {
	background-size: 30px auto;
	background-repeat: no-repeat;
	background-position: left center;
